{"command":"python3 -c '
import pty
import os
import sys
import select
import time

def run_with_pty():
    pid, fd = pty.fork()
    if pid == 0:
        os.execv("./executable", ["./executable"])
    else:
        output = b""
        start_time = time.time()
        while True:
            r, w, x = select.select([fd], [], [], 0.5)
            if fd in r:
                try:
                    data = os.read(fd, 1024)
                    if not data:
                        break
                    output += data
                    if b"\x1b]11;?\x1b\\" in data:
                        # Respond with background color (black)
                        os.write(fd, b"\x1b]11;rgb:0000/0000/0000\x1b\\")
                    if b"\x1b[6n" in data:
                        # Respond with cursor position
                        os.write(fd, b"\x1b[24;1R")
                except OSError:
                    break
            else:
                # Timeout, send quit
                if time.time() - start_time > 1:
                    os.write(fd, b"q")
                    break

        # Keep reading until exit
        while True:
            r, w, x = select.select([fd], [], [], 0.5)
            if fd in r:
                try:
                    data = os.read(fd, 1024)
                    if not data:
                        break
                    output += data
                except OSError:
                    break
            else:
                break

        with open("output2.txt", "wb") as f:
            f.write(output)

run_with_pty()
