    os.system(f"rm -rf testdir2 && mkdir testdir2")
    for i in range(num_items):
        open(f"testdir2/f_{i:03d}", "w").close()

    pid, fd = pty.fork()
    if pid == 0:
        os.environ["TERM"] = "xterm-256color"
        os.chdir("testdir2")
        os.execv("../executable", ["../executable"])
    else:
        winsize = struct.pack("HHHH", height, 80, 0, 0)
        fcntl.ioctl(fd, termios.TIOCSWINSZ, winsize)

        output = b""
        start_time = time.time()
        stage = 0
        while True:
            r, w, x = select.select([fd], [], [], 0.2)
            if fd in r:
                try:
                    data = os.read(fd, 1024)
                    if not data:
                        break
                    output += data
                    if b"\x1b]11;?\x1b\\" in data:
                        os.write(fd, b"\x1b]11;rgb:0000/0000/0000\x1b\\")
                    if b"\x1b[6n" in data:
                        os.write(fd, f"\x1b[{height};1R".encode())
                except OSError:
                    break
            else:
                if stage == 0:
                    os.write(fd, b"q")
                    break

        while True:
            r, w, x = select.select([fd], [], [], 0.2)
            if fd in r:
                try:
                    data = os.read(fd, 1024)
                    if not data:
                        break
                    output += data
                except OSError:
                    break
            else:
                break

        match = re.search(rb'\x1b\[(\d+)A', output)
        if match:
            print(f"Items: {num_items:3d}, Height: {height:3d} -> Rows: {int(match.group(1))}")
        else:
            print(f"Items: {num_items:3d}, Height: {height:3d} -> Rows: Not found")

