			flags.Icons = true
		case "--dir-only":
			flags.DirOnly = true
		case "--hide-hidden":
			flags.HideHidden = true
		case "--preview":
			flags.Preview = true
		case "--with-border":
			flags.WithBorder = true
		case "--fuzzy":
			flags.Fuzzy = true
		default:
			if !strings.HasPrefix(args[i], "-") {
				cwd = args[i]
			}
		}
	}

	if cwd == "" {
		cwd, _ = os.Getwd()
	}
	cwd, _ = filepath.Abs(cwd)

	initTerm()

	// Initial file load
	loadFiles()

	// Loop
	runTUI()
}

func initTerm() {
	fd := int(os.Stdin.Fd())
	ws, err := unix.IoctlGetWinsize(fd, unix.TIOCGWINSZ)
	if err == nil {
		termWidth = int(ws.Col)
		termHeight = int(ws.Row)
	}

	fmt.Print("\x1b]11;?\x1b\\\x1b[6n") // Query bg color and cursor pos
	// Note: We don't strictly wait for response to avoid hanging if terminal doesn't support it.
	// We set raw mode for interaction.
}

func loadFiles() {
	entries, err := os.ReadDir(cwd)
	if err != nil {
		entries = []fs.DirEntry{}
	}

	files = []fs.DirEntry{}
	for _, e := range entries {
		name := e.Name()
		if flags.HideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if flags.DirOnly && !e.IsDir() {
			continue
		}
		if flags.Fuzzy && query != "" {
			if !strings.Contains(strings.ToLower(name), strings.ToLower(query)) {
				continue
			}
		}
		files = append(files, e)
	}

	sort.Slice(files, func(i, j int) bool {
		// Dirs first
		if files[i].IsDir() && !files[j].IsDir() {
			return true
		}
		if !files[i].IsDir() && files[j].IsDir() {
			return false
		}
		return strings.ToLower(files[i].Name()) < strings.ToLower(files[j].Name())
	})

	if cursorIdx >= len(files) {
		cursorIdx = len(files) - 1
	}
	if cursorIdx < 0 {
		cursorIdx = 0
	}
}

func formatName(e fs.DirEntry) string {
	name := e.Name()
	if e.IsDir() {
		name += "/"
	}
	if !flags.Icons {
		return name
	}
	icon := " " // default file
	if e.IsDir() {
		icon = " "
	} else if e.Type()&fs.ModeSymlink != 0 {
		icon = " "
	} else if e.Type()&0111 != 0 {
		icon = " "
	} else {
		ext := strings.ToLower(filepath.Ext(name))
		switch ext {
		case ".go": icon = " "
		case ".py": icon = " "
		case ".md": icon = " "
		case ".txt": icon = " "
		case ".gitignore": icon = " "
		case "":
			if name == "LICENSE" {
				icon = " "
			}
		}
	}
	return icon + name
}

// Will continue drawing logic
EOF
