func getGridCols(numItems int) int {
	if numItems == 0 {
		return 1
	}
	targetRows := termHeight / 3
	if targetRows < 8 {
		targetRows = 8
	}

	cols := 1
	for c := 1; c <= numItems; c++ {
		r := (numItems + c - 1) / c
		allowedRows := targetRows
		if c == 1 && allowedRows < 10 {
			allowedRows = 10
		}
		if c == 2 && allowedRows < 10 {
			allowedRows = 10
		}
		if c == 3 && allowedRows < 9 {
			allowedRows = 9
		}

		// Check max width
		width := 0
		for col := 0; col < c; col++ {
			maxW := 0
			for row := 0; row < r; row++ {
				idx := row*c + col
				if idx < numItems {
					w := len(formatName(files[idx]))
					if w > maxW {
						maxW = w
					}
				}
			}
			width += maxW
			if col < c-1 {
				width += 4
			}
		}

		if width > termWidth && c > 1 {
			return c - 1
		}

		cols = c
		if r <= allowedRows {
			break
		}
	}
	return cols
}

func getStatus() string {
	bar := os.Getenv("WALK_STATUS_BAR")
	if bar == "" || len(files) == 0 {
		return ""
	}

	f := files[cursorIdx]
	info, err := f.Info()
	if err != nil {
		return ""
	}

	env := map[string]interface{}{
		"current_file": f,
		"files":        files,
		"Size": func() string {
			if f.IsDir() {
				return ""
			}
			return fmt.Sprintf("%dB", info.Size()) // simplification
		},
		"Mode": func() string {
			return info.Mode().String()
		},
		"ModTime": func() string {
			return info.ModTime().Format("Jan 02 15:04")
		},
		"Owner": func() string {
			// simple mock for owner, properly needs sys/unix
			return "agent agent"
		},
		"Sprintf": fmt.Sprintf,
		"PadLeft": func(s string, n int) string {
			if len(s) >= n { return s }
			return strings.Repeat(" ", n-len(s)) + s
		},
		"PadRight": func(s string, n int) string {
			if len(s) >= n { return s }
			return s + strings.Repeat(" ", n-len(s))
		},
	}

	program, err := expr.Compile(bar, expr.Env(env))
	if err != nil {
		return ""
	}
	out, err := expr.Run(program, env)
	if err != nil {
		return ""
	}
	return fmt.Sprintf("%v", out)
}

func getTerminalState() (*term.State, error) {
	return term.MakeRaw(int(os.Stdin.Fd()))
}

func restoreTerminalState(state *term.State) {
	term.Restore(int(os.Stdin.Fd()), state)
}

