package main

import (
	"fmt"
	"io/fs"
	"os/user"
	"strconv"
	"strings"
	"syscall"

	"github.com/antonmedv/expr"
)

func humanSize(b int64) string {
	const unit = 1024
	if b < unit {
		return fmt.Sprintf("%dB", b)
	}
	div, exp := int64(unit), 0
	for n := b / unit; n >= unit; n /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f%c", float64(b)/float64(div), "KMGTPE"[exp])
}

func evaluateStatusBar() string {
	bar := os.Getenv("WALK_STATUS_BAR")
	if bar == "" || len(files) == 0 {
		return ""
	}

	f := files[cursorIdx]
	info, err := f.Info()
	if err != nil {
		return ""
	}

	env := map[string]interface{}{
		"current_file": f,
		"files":        files,
		"Size": func() string {
			if f.IsDir() {
				return ""
			}
			return humanSize(info.Size())
		},
		"Mode": func() string {
			return info.Mode().String()
		},
		"ModTime": func() string {
			return info.ModTime().Format("Jan 02 15:04")
		},
		"Owner": func() string {
			sys := info.Sys()
			if stat, ok := sys.(*syscall.Stat_t); ok {
				uid := strconv.Itoa(int(stat.Uid))
				gid := strconv.Itoa(int(stat.Gid))
				u, err := user.LookupId(uid)
				uname := uid
				if err == nil {
					uname = u.Username
				}
				g, err := user.LookupGroupId(gid)
				gname := gid
				if err == nil {
					gname = g.Name
				}
				return uname + " " + gname
			}
			return "user group"
		},
		"Sprintf": fmt.Sprintf,
		"PadLeft": func(s interface{}, n int) string {
			str := fmt.Sprint(s)
			if len(str) >= n {
				return str
			}
			return strings.Repeat(" ", n-len(str)) + str
		},
		"PadRight": func(s interface{}, n int) string {
			str := fmt.Sprint(s)
			if len(str) >= n {
				return str
			}
			return str + strings.Repeat(" ", n-len(str))
		},
	}

	program, err := expr.Compile(bar, expr.Env(env))
	if err != nil {
		return ""
	}
	out, err := expr.Run(program, env)
	if err != nil {
		return ""
	}

	if res, ok := out.([]interface{}); ok {
	    // If join is used, it might be handled by expr, but just in case
	    strs := []string{}
	    for _, v := range res {
	        strs = append(strs, fmt.Sprint(v))
	    }
	    return strings.Join(strs, " ")
	}

	if res, ok := out.([]string); ok {
	    return strings.Join(res, " ")
	}

	return fmt.Sprint(out)
}
EOF
"}

