{"command":"cat << 'EOF' > tui.go
package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func runTUI() {
	fd := int(os.Stdin.Fd())
	oldState, err := MakeRaw(fd)
	if err == nil {
		defer Restore(fd, oldState)
	}

	fmt.Print("\x1b[?25l\x1b[?2004h\r")

	firstDraw := true
	for {
		if !firstDraw {
			// Move cursor up to redraw
			if drawnRows > 0 {
				fmt.Printf("\x1b[80D\x1b[%dA", drawnRows)
			} else {
				fmt.Print("\r")
			}
		}
		firstDraw = false

		draw()

		buf := make([]byte, 1024)
		n, _ := os.Stdin.Read(buf)
		if n == 0 {
			break
		}

		// Parse keys
		seq := string(buf[:n])

		if flags.Fuzzy {
			if seq == "\x03" || seq == "\x1b" { // Ctrl+C or Esc clears fuzzy or exits
				if query != "" {
					query = ""
					cursorIdx = 0
					loadFiles()
					continue
				} else if seq == "\x03" {
					cwd = "" // Exits without cd
					break
				} else {
					break
				}
			} else if seq == "\x7f" { // Backspace
				if len(query) > 0 {
					query = query[:len(query)-1]
					cursorIdx = 0
					loadFiles()
				} else {
					// Fallback to exit dir
					cwd = filepath.Dir(cwd)
					cursorIdx = 0
					loadFiles()
				}
				continue
			} else if seq == "\r" || seq == "\n" {
				handleEnter(fd, oldState)
				continue
			} else if len(seq) == 1 && seq[0] >= 32 && seq[0] <= 126 {
				query += seq
				cursorIdx = 0
				loadFiles()
				continue
			} else if seq == "\x1b[A" {
				moveCursor(-1, 0)
				continue
			} else if seq == "\x1b[B" {
				moveCursor(1, 0)
				continue
			} else if seq == "\x1b[D" {
				moveCursor(0, -1)
				continue
			} else if seq == "\x1b[C" {
				moveCursor(0, 1)
				continue
			}
		} else {
			if seq == "\x03" { // Ctrl+C
				cwd = "" // Exits without cd
				break
			}
			if seq == "q" || seq == "\x1b" { // Esc or q
				break
			}
			if seq == "\r" || seq == "\n" { // Enter
				handleEnter(fd, oldState)
				continue
			}
			if seq == "\x7f" { // Backspace
				cwd = filepath.Dir(cwd)
				cursorIdx = 0
				loadFiles()
				continue
			}
			if seq == " " { // Space toggles preview
				flags.Preview = !flags.Preview
				if flags.Preview {
					fmt.Print("\x1b[?1049h\x1b[24;H\x1b[H") // Enter alt screen
				} else {
					fmt.Print("\x1b[?1049l\x1b[?25h")      // Exit alt screen
				}
				continue
			}
			if seq == "/" {
				flags.Fuzzy = true
				continue
			}
			if seq == "." {
				flags.HideHidden = !flags.HideHidden
				cursorIdx = 0
				loadFiles()
				continue
			}
			if seq == "\x1b[A" || seq == "k" {
				moveCursor(-1, 0)
			} else if seq == "\x1b[B" || seq == "j" {
				moveCursor(1, 0)
			} else if seq == "\x1b[D" || seq == "h" {
				moveCursor(0, -1)
			} else if seq == "\x1b[C" || seq == "l" {
				moveCursor(0, 1)
			}
		}
	}

	exitTUI()
}

func handleEnter(fd int, oldState *syscall.Termios) {
	if len(files) == 0 {
		return
	}
	f := files[cursorIdx]
	if f.IsDir() {
		cwd = filepath.Join(cwd, f.Name())
		cursorIdx = 0
		loadFiles()
		if flags.Fuzzy {
			query = ""
		}
	} else {
		// Open file
		editor := os.Getenv("WALK_EDITOR")
		if editor == "" {
			editor = os.Getenv("EDITOR")
		}
		if editor != "" {
			Restore(fd, oldState)
