	c := getGridCols(len(files))
	r := 0
	if c > 0 {
		r = (len(files) + c - 1) / c
	}

	colWidths := make([]int, c)
	for col := 0; col < c; col++ {
		maxW := 0
		for row := 0; row < r; row++ {
			idx := col*r + row
			if idx < len(files) {
				w := len(formatName(files[idx]))
				if w > maxW {
					maxW = w
				}
			}
		}
		colWidths[col] = maxW
	}

	for row := 0; row < r; row++ {
		for col := 0; col < c; col++ {
			idx := col*r + row
			if idx >= len(files) {
				continue
			}

			name := formatName(files[idx])
