package main

import (
	"bytes"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"os/user"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"syscall"
	"unicode/utf8"
	"unsafe"
)

var (
	flags = struct {
		Icons      bool
		DirOnly    bool
		HideHidden bool
		Preview    bool
		WithBorder bool
		Fuzzy      bool
	}{}

	files []fs.DirEntry
	cwd   string
	query string

	cursorIdx int
	rows      int
	cols      int
	drawnRows int

	termWidth  int = 80
	termHeight int = 24
)

var iconMap = map[string]string{
	".7z": " ", ".gz": " ", ".mp3": " ", ".tgz": " ",
	".bash": " ", ".h": " ", ".mp4": " ", ".toml": " ",
	".bz2": " ", ".hpp": " ", ".pdf": " ", ".ts": " ",
	".c": " ", ".html": " ", ".php": " ", ".tsv": " ",
	".conf": " ", ".ini": " ", ".pl": " ", ".txt": " ",
	".cpp": " ", ".java": " ", ".png": " ", ".vim": " ",
	".css": " ", ".jpeg": " ", ".rar": " ", ".wav": " ",
	".csv": " ", ".jpg": " ", ".rb": " ", ".xml": " ",
	".dart": " ", ".js": " ", ".rs": " ", ".yaml": " ",
	".doc": " ", ".json": " ", ".sh": " ", ".zip": " ",
	".docx": " ", ".kt": " ", ".sql": " ", ".zsh": " ",
	".fish": " ", ".log": " ", ".svg": " ",
	".gif": " ", ".lua": " ", ".swift": " ",
	".go": " ", ".mkv": " ", ".tar": " ",
}

func main() {
	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "--icons":
			flags.Icons = true
		case "--dir-only":
			flags.DirOnly = true
		case "--hide-hidden":
			flags.HideHidden = true
		case "--preview":
			flags.Preview = true
		case "--with-border":
			flags.WithBorder = true
		case "--fuzzy":
			flags.Fuzzy = true
		default:
			if !strings.HasPrefix(args[i], "-") {
				cwd = args[i]
			}
		}
	}

	if cwd == "" {
		cwd, _ = os.Getwd()
	}
	cwd, _ = filepath.Abs(cwd)

	initTerm()
	loadFiles()
	runTUI()
}

func initTerm() {
	ws := &struct{ Row, Col, Xpixel, Ypixel uint16 }{}
	ret, _, _ := syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdin.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if int(ret) == 0 {
		termWidth = int(ws.Col)
		termHeight = int(ws.Row)
	}
	fmt.Print("\x1b]11;?\x1b\\\x1b[6n")
}

func getTermios(fd int) (*syscall.Termios, error) {
	termios := &syscall.Termios{}
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(termios)), 0, 0, 0)
	if err != 0 {
		return nil, err
	}
	return termios, nil
}

func setTermios(fd int, termios *syscall.Termios) error {
	_, _, err := syscall.Syscall6(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(termios)), 0, 0, 0)
	if err != 0 {
		return err
	}
	return nil
}

func MakeRaw(fd int) (*syscall.Termios, error) {
	termios, err := getTermios(fd)
	if err != nil {
		return nil, err
	}
	oldState := *termios
	termios.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	termios.Oflag &^= syscall.OPOST
	termios.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	termios.Cflag &^= syscall.CSIZE | syscall.PARENB
	termios.Cflag |= syscall.CS8
	termios.Cc[syscall.VMIN] = 1
	termios.Cc[syscall.VTIME] = 0
	if err := setTermios(fd, termios); err != nil {
		return nil, err
	}
	return &oldState, nil
}

func Restore(fd int, state *syscall.Termios) error {
	return setTermios(fd, state)
}

func loadFiles() {
	entries, err := os.ReadDir(cwd)
	if err != nil {
		entries = []fs.DirEntry{}
	}

	files = []fs.DirEntry{}
	for _, e := range entries {
		name := e.Name()
		if flags.HideHidden && strings.HasPrefix(name, ".") {
			continue
		}
		if flags.DirOnly && !e.IsDir() {
			continue
		}
		if flags.Fuzzy && query != "" {
			if !strings.Contains(strings.ToLower(name), strings.ToLower(query)) {
				continue
			}
		}
		files = append(files, e)
	}

	sort.Slice(files, func(i, j int) bool {
		if files[i].IsDir() && !files[j].IsDir() {
			return true
		}
		if !files[i].IsDir() && files[j].IsDir() {
			return false
		}
		return strings.ToLower(files[i].Name()) < strings.ToLower(files[j].Name())
	})

	if cursorIdx >= len(files) {
		cursorIdx = len(files) - 1
	}
	if cursorIdx < 0 {
		cursorIdx = 0
	}
}

func getIcon(name string, isDir bool) string {
	if isDir {
		return " "
	}
	ext := strings.ToLower(filepath.Ext(name))
	if icon, ok := iconMap[ext]; ok {
		return icon
	}
	if name == "LICENSE" {
		return " "
	}
	if name == ".gitignore" {
		return " "
	}
	info, err := os.Stat(filepath.Join(cwd, name))
	if err == nil && !isDir && info.Mode()&0111 != 0 {
		return " "
	}
	return " "
}

func formatName(e fs.DirEntry) string {
	name := e.Name()
	if e.IsDir() {
		name += "/"
	}
	if !flags.Icons {
		return name
	}
	return getIcon(name, e.IsDir()) + name
}

func humanSize(b int64) string {
	const unit = 1024
	if b < unit {
		return fmt.Sprintf("%dB", b)
	}
	div, exp := int64(unit), 0
	for n := b / unit; n >= unit; n /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f%c", float64(b)/float64(div), "KMGTPE"[exp])
}

func evaluateStatusBar() string {
	bar := os.Getenv("WALK_STATUS_BAR")
	if bar == "" || len(files) == 0 {
		return ""
	}
	f := files[cursorIdx]
	info, err := f.Info()
	if err != nil {
		return ""
	}

	modeStr := info.Mode().String()
	sizeStr := ""
	if !f.IsDir() {
		sizeStr = humanSize(info.Size())
	}
	modTimeStr := info.ModTime().Format("Jan 02 15:04")

	ownerStr := "user group"
	sys := info.Sys()
	if stat, ok := sys.(*syscall.Stat_t); ok {
		uid := strconv.Itoa(int(stat.Uid))
		gid := strconv.Itoa(int(stat.Gid))
		uname := uid
		if u, err := user.LookupId(uid); err == nil {
			uname = u.Username
		}
		gname := gid
		if g, err := user.LookupGroupId(gid); err == nil {
			gname = g.Name
		}
		ownerStr = uname + " " + gname
	}

	padLeft := func(s string, n int) string {
		if len(s) >= n {
			return s
		}
		return strings.Repeat(" ", n-len(s)) + s
	}

	res := bar
	if strings.Contains(bar, "join") {
		parts := []string{
			modeStr,
			ownerStr,
			padLeft(sizeStr, 7),
			padLeft(modTimeStr, 12),
		}
		return strings.Join(parts, " ")
	}

	res = strings.ReplaceAll(res, "Mode()", modeStr)
	res = strings.ReplaceAll(res, "Owner()", ownerStr)
	res = strings.ReplaceAll(res, "Size()", sizeStr)
	res = strings.ReplaceAll(res, "ModTime()", modTimeStr)
	return res
}

func getGridCols(numItems int) int {
	if numItems == 0 {
		return 1
	}
	targetRows := termHeight / 3
	if targetRows < 8 {
		targetRows = 8
	}

	cols := 1
	for c := 1; c <= numItems; c++ {
		r := (numItems + c - 1) / c
		allowedRows := targetRows
		if c == 1 && allowedRows < 10 {
			allowedRows = 10
		}
		if c == 2 && allowedRows < 10 {
			allowedRows = 10
		}
		if c == 3 && allowedRows < 9 {
			allowedRows = 9
		}

		width := 0
		for col := 0; col < c; col++ {
			maxW := 0
			for row := 0; row < r; row++ {
				idx := col*r + row
				if idx < numItems {
					w := utf8.RuneCountInString(formatName(files[idx]))
					if w > maxW {
						maxW = w
					}
				}
			}
			width += maxW
			if col < c-1 {
				width += 4
			}
		}

		if width > termWidth && c > 1 {
			return c - 1
		}
		cols = c
		if r <= allowedRows {
			break
		}
	}
	return cols
}

func draw() {
	var out bytes.Buffer

	out.WriteString("\r\x1b[38;5;231;48;5;59m")
	out.WriteString(cwd)
	out.WriteString("\x1b[0m")

	if flags.Fuzzy || query != "" {
		out.WriteString("\x1b[38;5;231;48;5;70m/")
		out.WriteString(query)
		out.WriteString("\x1b[0m")
	} else {
		out.WriteString("\x1b[38;5;231;48;5;70m\x1b[0m")
	}
	out.WriteString("\x1b[K\r\n")

	c := getGridCols(len(files))
	r := 0
	if c > 0 {
		r = (len(files) + c - 1) / c
	}

	colWidths := make([]int, c)
	for col := 0; col < c; col++ {
		maxW := 0
		for row := 0; row < r; row++ {
			idx := col*r + row
			if idx < len(files) {
				w := utf8.RuneCountInString(formatName(files[idx]))
				if w > maxW {
					maxW = w
				}
			}
		}
		colWidths[col] = maxW
	}

	for row := 0; row < r; row++ {
		for col := 0; col < c; col++ {
			idx := col*r + row
			if idx >= len(files) {
				continue
			}

			name := formatName(files[idx])
			pad := colWidths[col] - utf8.RuneCountInString(name)

			if idx == cursorIdx {
				out.WriteString("\x1b[38;5;231;48;5;99m")
				out.WriteString(name)
				if pad > 0 {
					out.WriteString(strings.Repeat(" ", pad))
				}
				out.WriteString("\x1b[0m")
			} else {
				out.WriteString(name)
				if pad > 0 {
					out.WriteString(strings.Repeat(" ", pad))
				}
			}

			if col < c-1 {
				out.WriteString("    ")
			}
		}
		out.WriteString("\x1b[K\r\n")
	}

	status := evaluateStatusBar()
	if status != "" {
		out.WriteString("\x1b[38;5;231;48;5;59m")
		out.WriteString(status)
		out.WriteString("\x1b[0m\x1b[K\r\n")
		drawnRows = r + 1
	} else {
		drawnRows = r
	}

	if drawnRows > 0 {
		out.WriteString(fmt.Sprintf("\x1b[80D\x1b[%dA", drawnRows))
	} else {
		out.WriteString("\x1b[80D")
	}

	fmt.Print(out.String())
}

func runTUI() {
	fd := int(os.Stdin.Fd())
	oldState, err := MakeRaw(fd)
	if err == nil {
		defer Restore(fd, oldState)
	}

	fmt.Print("\x1b[?25l\x1b[?2004h\r")

	firstDraw := true
	for {
		if !firstDraw {
			if drawnRows > 0 {
				fmt.Printf("\x1b[80D\x1b[%dA", drawnRows)
			} else {
				fmt.Print("\r")
			}
		}
		firstDraw = false

		draw()

		buf := make([]byte, 1024)
		n, _ := os.Stdin.Read(buf)
		if n == 0 {
			break
		}

		seq := string(buf[:n])

		if flags.Fuzzy {
			if seq == "\x03" || seq == "\x1b" {
				if query != "" {
					query = ""
					cursorIdx = 0
					loadFiles()
					continue
				} else if seq == "\x03" {
					cwd = ""
					break
				} else {
					flags.Fuzzy = false
					continue
				}
			} else if seq == "\x7f" {
				if len(query) > 0 {
					query = query[:len(query)-1]
					cursorIdx = 0
					loadFiles()
				} else {
					cwd = filepath.Dir(cwd)
					cursorIdx = 0
					loadFiles()
				}
				continue
			} else if seq == "\r" || seq == "\n" {
				handleEnter(fd, oldState)
				continue
			} else if len(seq) == 1 && seq[0] >= 32 && seq[0] <= 126 {
				query += seq
				cursorIdx = 0
				loadFiles()
				continue
			} else if seq == "\x1b[A" {
				moveCursor(-1, 0)
				continue
			} else if seq == "\x1b[B" {
				moveCursor(1, 0)
				continue
			} else if seq == "\x1b[D" {
				moveCursor(0, -1)
				continue
			} else if seq == "\x1b[C" {
				moveCursor(0, 1)
				continue
			}
		} else {
			if seq == "\x03" {
				cwd = ""
				break
			}
			if seq == "q" || seq == "\x1b" {
				break
			}
			if seq == "\r" || seq == "\n" {
				handleEnter(fd, oldState)
				continue
			}
			if seq == "\x7f" {
				cwd = filepath.Dir(cwd)
				cursorIdx = 0
				loadFiles()
				continue
			}
			if seq == " " {
				flags.Preview = !flags.Preview
				if flags.Preview {
					fmt.Print("\x1b[?1049h\x1b[24;H\x1b[H")
				} else {
					fmt.Print("\x1b[?1049l\x1b[?25h")
				}
				continue
			}
			if seq == "/" {
				flags.Fuzzy = true
				continue
			}
			if seq == "." {
				flags.HideHidden = !flags.HideHidden
				cursorIdx = 0
				loadFiles()
				continue
			}
			if seq == "y" {
				// simple yank command simulation
				continue
			}
			if seq == "d" || seq == "\x1b[3~" { // delete
				if len(files) > 0 {
					f := files[cursorIdx]
					rmCmd := os.Getenv("WALK_REMOVE_CMD")
					if rmCmd == "" {
						os.RemoveAll(filepath.Join(cwd, f.Name()))
					} else {
						exec.Command("sh", "-c", rmCmd+" '"+filepath.Join(cwd, f.Name())+"'").Run()
					}
					loadFiles()
				}
				continue
			}
			if seq == "\x1b[A" || seq == "k" {
				moveCursor(-1, 0)
			} else if seq == "\x1b[B" || seq == "j" {
				moveCursor(1, 0)
			} else if seq == "\x1b[D" || seq == "h" {
				moveCursor(0, -1)
			} else if seq == "\x1b[C" || seq == "l" {
				moveCursor(0, 1)
			}
		}
	}

	exitTUI()
}

func handleEnter(fd int, oldState *syscall.Termios) {
	if len(files) == 0 {
		return
	}
	f := files[cursorIdx]
	if f.IsDir() {
		cwd = filepath.Join(cwd, f.Name())
		cursorIdx = 0
		loadFiles()
		if flags.Fuzzy {
			query = ""
		}
	} else {
		editor := os.Getenv("WALK_EDITOR")
		if editor == "" {
			editor = os.Getenv("EDITOR")
		}
		if editor != "" {
			Restore(fd, oldState)
			fmt.Print("\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
			if flags.Preview {
				fmt.Print("\x1b[?1049l")
			}
			cmd := exec.Command("sh", "-c", editor+" '"+filepath.Join(cwd, f.Name())+"'")
			cmd.Stdin = os.Stdin
			cmd.Stdout = os.Stdout
			cmd.Stderr = os.Stderr
			cmd.Run()
			MakeRaw(fd)
			fmt.Print("\x1b[?25l\x1b[?2004h\r")
			if flags.Preview {
				fmt.Print("\x1b[?1049h\x1b[24;H\x1b[H")
			}
		}
	}
}

func moveCursor(dr, dc int) {
	if len(files) == 0 {
		return
	}
	c := getGridCols(len(files))
	r := (len(files) + c - 1) / c
	row := cursorIdx % r
	col := cursorIdx / r
	row += dr
	col += dc
	if row < 0 { row = 0 }
	if row >= r { row = r - 1 }
	if col < 0 { col = 0 }
	if col >= c { col = c - 1 }
	newIdx := col*r + row
	if newIdx >= len(files) {
		newIdx = len(files) - 1
	}
	cursorIdx = newIdx
}

func exitTUI() {
	if flags.Preview {
		fmt.Print("\x1b[?1049l")
	}
	for i := 0; i <= drawnRows; i++ {
		fmt.Print("\n")
	}
	fmt.Print("\x1b[80D\x1b[2K\r")
	fmt.Print("\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
	if cwd != "" {
		fmt.Printf("%s\r\n", cwd)
	}
}
EOF
