sed -i 's/func draw()/func draw(firstDraw bool)/' main.go
sed -i '/out.WriteString("\r\x1b\[38;5;231;48;5;59m")/i \	if !firstDraw {
		out.WriteString("\x1b[1A\r")
	}' main.go
sed -i 's/draw()/draw(false)/g' main.go
sed -i 's/for {/firstDraw := true
	for {
		draw(firstDraw)
		firstDraw = false/' main.go
./compile.sh
